import{_ as p,a0 as o,w as d,s as u,I as a,x as n,a1 as t,A as e,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"使用 Cloud-init 将节点添加到你的私有云中 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Cloud-init 将节点添加到你的私有云中 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Cloud-init 将节点添加到你的私有云中 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Cloud-init 将节点添加到你的私有云中 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200527 Add nodes to your private cloud using Cloud-init","title":"使用 Cloud-init 将节点添加到你的私有云中","tag":"202007","desc":""},"relativePath":"202007/20200527 Add nodes to your private cloud using Cloud-init.md","filePath":"[post].md"}'),r={name:"202007/20200527 Add nodes to your private cloud using Cloud-init.md"};function c(g,s,h,b,k,f){const i=o("Link");return d(),u("div",null,[s[44]||(s[44]=a("h1",{id:"使用-cloud-init-将节点添加到你的私有云中",tabindex:"-1"},[n("使用 Cloud-init 将节点添加到你的私有云中 "),a("a",{class:"header-anchor",href:"#使用-cloud-init-将节点添加到你的私有云中","aria-label":"Permalink to “使用 Cloud-init 将节点添加到你的私有云中”"},"​")],-1)),s[45]||(s[45]=a("blockquote",null,[a("p",null,"像主流云提供商的处理方式一样，在家中添加机器到你的私有云。")],-1)),s[46]||(s[46]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202007/12/100823rj096h3ax4hhehey.jpg",alt:""})],-1)),a("p",null,[t(i,{href:"https://cloudinit.readthedocs.io/"},{default:e(()=>[...s[0]||(s[0]=[n("Cloud-init",-1)])]),_:1}),s[2]||(s[2]=n(" 是一种广泛使用的行业标准方法，用于初始化云实例。云提供商使用 Cloud-init 来定制实例的网络配置、实例信息，甚至用户提供的配置指令。它也是一个可以在你的“家庭私有云”中使用的很好的工具，可以为你的家庭实验室的虚拟机和物理机的初始设置和配置添加一点自动化 —— 并了解更多关于大型云提供商是如何工作的信息。关于更多的细节和背景，请看我之前的文章《",-1)),t(i,{href:"https://linux.cn/article-12371-1.html"},{default:e(()=>[...s[1]||(s[1]=[n("在你的树莓派家庭实验室中使用 Cloud-init",-1)])]),_:1}),s[3]||(s[3]=n("》。",-1))]),s[47]||(s[47]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/uploads/cloud-init.jpg",alt:"A screen showing the boot process for a Linux server running Cloud-init ",title:"A screen showing the boot process for a Linux server running Cloud-init "})],-1)),a("p",null,[a("em",null,[s[5]||(s[5]=n("运行 Cloud-init 的 Linux 服务器的启动过程（Chris Collins，",-1)),t(i,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:e(()=>[...s[4]||(s[4]=[n("CC BY-SA 4.0",-1)])]),_:1}),s[6]||(s[6]=n("）",-1))])]),s[48]||(s[48]=a("p",null,"诚然，Cloud-init 对于为许多不同客户配置机器的云提供商来说，比对于由单个系统管理员运行的家庭实验室更有用，而且 Cloud-init 解决的许多问题对于家庭实验室来说可能有点多余。然而，设置它并了解它的工作原理是了解更多关于这种云技术的好方法，更不用说它是首次启动时配置设备的好方法。",-1)),s[49]||(s[49]=a("p",null,"本教程使用 Cloud-init 的 NoCloud 数据源，它允许 Cloud-init 在传统的云提供商环境之外使用。本文将向你展示如何在客户端设备上安装 Cloud-init，并设置一个运行 Web 服务的容器来响应客户端的请求。你还将学习如何审查客户端从 Web 服务中请求的内容，并修改 Web 服务的容器，以提供基本的、静态的 Cloud-init 服务。",-1)),s[50]||(s[50]=a("h3",{id:"在现有系统上设置-cloud-init",tabindex:"-1"},[n("在现有系统上设置 Cloud-init "),a("a",{class:"header-anchor",href:"#在现有系统上设置-cloud-init","aria-label":"Permalink to “在现有系统上设置 Cloud-init”"},"​")],-1)),a("p",null,[s[8]||(s[8]=n("Cloud-init 可能在新系统首次启动时最有用，它可以查询配置数据，并根据指令对系统进行定制。它可以",-1)),t(i,{href:"https://linux.cn/article-12277-1.html"},{default:e(()=>[...s[7]||(s[7]=[n("包含在树莓派和单板计算机的磁盘镜像中",-1)])]),_:1}),s[9]||(s[9]=n("，也可以添加到用于",-1)),s[10]||(s[10]=a("ruby",null,[n("配给"),a("rt",null,"provision")],-1)),s[11]||(s[11]=n("虚拟机的镜像中。对于测试用途来说，无论是在现有系统上安装并运行 Cloud-init，还是安装一个新系统，然后设置 Cloud-init，都是很容易的。",-1))]),s[51]||(s[51]=l(`<p>作为大多数云提供商使用的主要服务，大多数 Linux 发行版都支持 Cloud-init。在这个例子中，我将使用 Fedora 31 Server 来安装树莓派，但在 Raspbian、Ubuntu、CentOS 和大多数其他发行版上也可以用同样的方式来完成。</p><h4 id="安装并启用云计算初始服务" tabindex="-1">安装并启用云计算初始服务 <a class="header-anchor" href="#安装并启用云计算初始服务" aria-label="Permalink to “安装并启用云计算初始服务”">​</a></h4><p>在你想作为 Cloud-init 客户端的系统上，安装 Cloud-init 包。如果你使用的是 Fedora：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Install the cloud-init package</span></span>
<span class="line"><span>dnf install -y cloud-init</span></span></code></pre></div><p>Cloud-init 实际上是四个不同的服务（至少在 systemd 下是这样），这些服务负责检索配置数据，并在启动过程的不同阶段进行配置更改，这使得可以做的事情更加灵活。虽然你不太可能直接与这些服务进行太多交互，但在你需要排除一些故障时，知道它们是什么还是很有用的。它们是：</p><ul><li>cloud-init-local.service</li><li>cloud-init.service</li><li>cloud-config.service</li><li>cloud-final.service</li></ul><p>启用所有四个服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Enable the four cloud-init services</span></span>
<span class="line"><span>systemctl enable cloud-init-local.service</span></span>
<span class="line"><span>systemctl enable cloud-init.service</span></span>
<span class="line"><span>systemctl enable cloud-config.service</span></span>
<span class="line"><span>systemctl enable cloud-final.service</span></span></code></pre></div><h4 id="配置数据源以查询" tabindex="-1">配置数据源以查询 <a class="header-anchor" href="#配置数据源以查询" aria-label="Permalink to “配置数据源以查询”">​</a></h4>`,9)),a("p",null,[s[13]||(s[13]=n("启用服务后，请配置数据源，客户端将从该数据源查询配置数据。有",-1)),t(i,{href:"https://cloudinit.readthedocs.io/en/latest/topics/datasources.html"},{default:e(()=>[...s[12]||(s[12]=[n("许多数据源类型",-1)])]),_:1}),s[14]||(s[14]=n("，而且大多数都是为特定的云提供商配置的。对于你的家庭实验室，请使用 NoCloud 数据源，（如上所述）它是为在没有云提供商的情况下使用 Cloud-init 而设计的。",-1))]),s[52]||(s[52]=l(`<p>NoCloud 允许以多种方式包含配置信息：以内核参数中的键/值对，用于在启动时挂载的 CD（或虚拟机中的虚拟 CD）；包含在文件系统中的文件中；或者像本例中一样，通过 HTTP 从指定的 URL（“NoCloud Net” 选项）获取配置信息。</p><p>数据源配置可以通过内核参数提供，也可以在 Cloud-init 配置文件 <code>/etc/cloud/cloud.cfg</code> 中进行设置。该配置文件对于使用自定义磁盘镜像设置 Cloud-init 或在现有主机上进行测试非常方便。</p><p>Cloud-init 还会合并在 <code>/etc/cloud/cloud.cfg.d/</code> 中找到的任何 <code>*.cfg</code> 文件中的配置数据，因此为了保持整洁，请在 <code>/etc/cloud/cloud.cfg.d/10_datasource.cfg</code> 中配置数据源。Cloud-init 可以通过使用以下语法从 <code>seedfrom</code> 键指向的 HTTP 数据源中读取数据。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>seedfrom: http://ip_address:port/</span></span></code></pre></div><p>IP 地址和端口是你将在本文后面创建的 Web 服务。我使用了我的笔记本电脑的 IP 和 8080 端口。这也可以是 DNS 名称。</p><p>创建 <code>/etc/cloud/cloud.cfg.d/10_datasource.cfg</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Add the datasource:</span></span>
<span class="line"><span># /etc/cloud/cloud.cfg.d/10_datasource.cfg</span></span>
<span class="line"><span></span></span>
<span class="line"><span># NOTE THE TRAILING SLASH HERE!</span></span>
<span class="line"><span>datasource:</span></span>
<span class="line"><span>  NoCloud:</span></span>
<span class="line"><span>    seedfrom: http://ip_address:port/</span></span></code></pre></div><p>客户端设置就是这样。现在，重新启动客户端后，它将尝试从你在 <code>seedfrom</code> 键中输入的 URL 检索配置数据，并进行必要的任何配置更改。</p><p>下一步是设置一个 Web 服务器来侦听客户端请求，以便你确定需要提供的服务。</p><h3 id="设置网络服务器以审查客户请求" tabindex="-1">设置网络服务器以审查客户请求 <a class="header-anchor" href="#设置网络服务器以审查客户请求" aria-label="Permalink to “设置网络服务器以审查客户请求”">​</a></h3>`,10)),a("p",null,[s[16]||(s[16]=n("你可以使用 ",-1)),t(i,{href:"https://podman.io/"},{default:e(()=>[...s[15]||(s[15]=[n("Podman",-1)])]),_:1}),s[17]||(s[17]=n(" 或其他容器编排工具（如 Docker 或 Kubernetes）快速创建和运行 Web 服务器。这个例子使用的是 Podman，但同样的命令也适用于 Docker。",-1))]),s[53]||(s[53]=l(`<p>要开始，请使用 <code>fedora:31</code> 容器镜像并创建一个容器文件（对于 Docker 来说，这会是一个 Dockerfile）来安装和配置 Nginx。从该容器文件中，你可以构建一个自定义镜像，并在你希望提供 Cloud-init 服务的主机上运行它。</p><p>创建一个包含以下内容的容器文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FROM fedora:31</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ENV NGINX_CONF_DIR &quot;/etc/nginx/default.d&quot;</span></span>
<span class="line"><span>ENV NGINX_LOG_DIR &quot;/var/log/nginx&quot;</span></span>
<span class="line"><span>ENV NGINX_CONF &quot;/etc/nginx/nginx.conf&quot;</span></span>
<span class="line"><span>ENV WWW_DIR &quot;/usr/share/nginx/html&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Install Nginx and clear the yum cache</span></span>
<span class="line"><span>RUN dnf install -y nginx \\</span></span>
<span class="line"><span>      &amp;&amp; dnf clean all \\</span></span>
<span class="line"><span>      &amp;&amp; rm -rf /var/cache/yum</span></span>
<span class="line"><span></span></span>
<span class="line"><span># forward request and error logs to docker log collector</span></span>
<span class="line"><span>RUN ln -sf /dev/stdout \${NGINX_LOG_DIR}/access.log \\</span></span>
<span class="line"><span>    &amp;&amp; ln -sf /dev/stderr \${NGINX_LOG_DIR}/error.log</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Listen on port 8080, so root privileges are not required for podman</span></span>
<span class="line"><span>RUN sed -i -E &#39;s/(listen)([[:space:]]*)(\\[\\:\\:\\]\\:)?80;$/\\1\\2\\38080 default_server;/&#39; $NGINX_CONF</span></span>
<span class="line"><span>EXPOSE 8080</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Allow Nginx PID to be managed by non-root user</span></span>
<span class="line"><span>RUN sed -i &#39;/user nginx;/d&#39; $NGINX_CONF</span></span>
<span class="line"><span>RUN sed -i &#39;s/pid \\/run\\/nginx.pid;/pid \\/tmp\\/nginx.pid;/&#39; $NGINX_CONF</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Run as an unprivileged user</span></span>
<span class="line"><span>USER 1001</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CMD [&quot;nginx&quot;, &quot;-g&quot;, &quot;daemon off;&quot;]</span></span></code></pre></div>`,3)),a("p",null,[s[19]||(s[19]=n("注：本例中使用的容器文件和其他文件可以在本项目的 ",-1)),t(i,{href:"https://github.com/clcollins/homelabCloudInit/tree/master/simpleCloudInitService/data"},{default:e(()=>[...s[18]||(s[18]=[n("GitHub 仓库",-1)])]),_:1}),s[20]||(s[20]=n("中找到。",-1))]),s[54]||(s[54]=l(`<p>上面容器文件中最重要的部分是改变日志存储方式的部分（写到 STDOUT 而不是文件），这样你就可以在容器日志中看到进入该服务器的请求。其他的一些改变使你可以在没有 root 权限的情况下使用 Podman 运行容器，也可以在没有 root 权限的情况下运行容器中的进程。</p><p>在 Web 服务器上的第一个测试并不提供任何 Cloud-init 数据；只是用它来查看 Cloud-init 客户端的请求。</p><p>创建容器文件后，使用 Podman 构建并运行 Web 服务器镜像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Build the container image</span></span>
<span class="line"><span>$ podman build -f Containerfile -t cloud-init:01 .</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Create a container from the new image, and run it</span></span>
<span class="line"><span># It will listen on port 8080</span></span>
<span class="line"><span>$ podman run --rm -p 8080:8080 -it cloud-init:01</span></span></code></pre></div><p>这会运行一个容器，让你的终端连接到一个伪 TTY。一开始看起来什么都没有发生，但是对主机 8080 端口的请求会被路由到容器内的 Nginx 服务器，并且在终端窗口中会出现一条日志信息。这一点可以用主机上的 <code>curl</code> 命令进行测试。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Use curl to send an HTTP request to the Nginx container</span></span>
<span class="line"><span>$ curl http://localhost:8080</span></span></code></pre></div><p>运行该 <code>curl</code> 命令后，你应该会在终端窗口中看到类似这样的日志信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>127.0.0.1 - - [09/May/2020:19:25:10 +0000] &quot;GET / HTTP/1.1&quot; 200 5564 &quot;-&quot; &quot;curl/7.66.0&quot; &quot;-&quot;</span></span></code></pre></div><p>现在，有趣的部分来了：重启 Cloud-init 客户端，并观察 Nginx 日志，看看当客户端启动时， Cloud-init 向 Web 服务器发出了什么请求。</p><p>当客户端完成其启动过程时，你应该会看到类似的日志消息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2020/05/09 22:44:28 [error] 2#0: *4 open() &quot;/usr/share/nginx/html/meta-data&quot; failed (2: No such file or directory), client: 127.0.0.1, server: _, request: &quot;GET /meta-data HTTP/1.1&quot;, host: &quot;instance-data:8080&quot;</span></span>
<span class="line"><span>127.0.0.1 - - [09/May/2020:22:44:28 +0000] &quot;GET /meta-data HTTP/1.1&quot; 404 3650 &quot;-&quot; &quot;Cloud-Init/17.1&quot; &quot;-&quot;</span></span></code></pre></div><p>注：使用 <code>Ctrl+C</code> 停止正在运行的容器。</p><p>你可以看到请求是针对 <code>/meta-data</code> 路径的，即 <code>http://ip_address_of_the_webserver:8080/meta-data</code>。这只是一个 GET 请求 —— Cloud-init 并没有向 Web 服务器发送任何数据。它只是盲目地从数据源 URL 中请求文件，所以要由数据源来识别主机的要求。这个简单的例子只是向任何客户端发送通用数据，但一个更大的家庭实验室应该需要更复杂的服务。</p>`,13)),a("p",null,[s[22]||(s[22]=n("在这里，Cloud-init 请求的是",-1)),t(i,{href:"https://cloudinit.readthedocs.io/en/latest/topics/instancedata.html#what-is-instance-data"},{default:e(()=>[...s[21]||(s[21]=[n("实例元数据",-1)])]),_:1}),s[23]||(s[23]=n("信息。这个文件可以包含很多关于实例本身的信息，例如实例 ID、分配实例的主机名、云 ID，甚至网络信息。",-1))]),s[55]||(s[55]=l(`<p>创建一个包含实例 ID 和主机名的基本元数据文件，并尝试将其提供给 Cloud-init 客户端。</p><p>首先，创建一个可复制到容器镜像中的 <code>meta-data</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>instance-id: iid-local01</span></span>
<span class="line"><span>local-hostname: raspberry</span></span>
<span class="line"><span>hostname: raspberry</span></span></code></pre></div><p>实例 ID（<code>instance-id</code>）可以是任何东西。但是，如果你在 Cloud-init 运行后更改实例 ID，并且文件被送达客户端，就会触发 Cloud-init 再次运行。你可以使用这种机制来更新实例配置，但你应该意识到它是这种工作方式。</p><p><code>local-hostname</code> 和 <code>hostname</code> 键正如其名，它们会在 Cloud-init 运行时为客户端设置主机名信息。</p><p>在容器文件中添加以下行以将 <code>meta-data</code> 文件复制到新镜像中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Copy the meta-data file into the image for Nginx to serve it</span></span>
<span class="line"><span>COPY meta-data \${WWW_DIR}/meta-data</span></span></code></pre></div><p>现在，用元数据文件重建镜像（使用一个新的标签以方便故障排除），并用 Podman 创建并运行一个新的容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Build a new image named cloud-init:02</span></span>
<span class="line"><span>podman build -f Containerfile -t cloud-init:02 .</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Run a new container with this new meta-data file</span></span>
<span class="line"><span>podman run --rm -p 8080:8080 -it cloud-init:02</span></span></code></pre></div><p>新容器运行后，重启 Cloud-init 客户端，再次观察 Nginx 日志。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>127.0.0.1 - - [09/May/2020:22:54:32 +0000] &quot;GET /meta-data HTTP/1.1&quot; 200 63 &quot;-&quot; &quot;Cloud-Init/17.1&quot; &quot;-&quot;</span></span>
<span class="line"><span>2020/05/09 22:54:32 [error] 2#0: *2 open() &quot;/usr/share/nginx/html/user-data&quot; failed (2: No such file or directory), client: 127.0.0.1, server: _, request: &quot;GET /user-data HTTP/1.1&quot;, host: &quot;instance-data:8080&quot;</span></span>
<span class="line"><span>127.0.0.1 - - [09/May/2020:22:54:32 +0000] &quot;GET /user-data HTTP/1.1&quot; 404 3650 &quot;-&quot; &quot;Cloud-Init/17.1&quot; &quot;-&quot;</span></span></code></pre></div><p>你看，这次 <code>/meta-data</code> 路径被提供给了客户端。成功了！</p><p>然而，客户端接着在 <code>/user-data</code> 路径上寻找第二个文件。该文件包含实例所有者提供的配置数据，而不是来自云提供商的数据。对于一个家庭实验室来说，这两个都是你自己提供的。</p>`,13)),a("p",null,[s[25]||(s[25]=n("你可以使用",-1)),t(i,{href:"https://cloudinit.readthedocs.io/en/latest/topics/modules.html"},{default:e(()=>[...s[24]||(s[24]=[n("许多 user-data 模块",-1)])]),_:1}),s[26]||(s[26]=n("来配置你的实例。对于这个例子，只需使用 ",-1)),s[27]||(s[27]=a("code",null,"write_files",-1)),s[28]||(s[28]=n(" 模块在客户端创建一些测试文件，并验证 Cloud-init 是否工作。",-1))]),s[56]||(s[56]=l(`<p>创建一个包含以下内容的用户数据文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#cloud-config</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Create two files with example content using the write_files module</span></span>
<span class="line"><span>write_files:</span></span>
<span class="line"><span> - content: |</span></span>
<span class="line"><span>    &quot;Does cloud-init work?&quot;</span></span>
<span class="line"><span>   owner: root:root</span></span>
<span class="line"><span>   permissions: &#39;0644&#39;</span></span>
<span class="line"><span>   path: /srv/foo</span></span>
<span class="line"><span> - content: |</span></span>
<span class="line"><span>   &quot;IT SURE DOES!&quot;</span></span>
<span class="line"><span>   owner: root:root</span></span>
<span class="line"><span>   permissions: &#39;0644&#39;</span></span>
<span class="line"><span>   path: /srv/bar</span></span></code></pre></div><p>除了使用 Cloud-init 提供的 <code>user-data</code> 模块制作 YAML 文件外，你还可以将其制作成一个可执行脚本供 Cloud-init 运行。</p><p>创建 <code>user-data</code> 文件后，在容器文件中添加以下行，以便在重建映像时将其复制到镜像中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Copy the user-data file into the container image</span></span>
<span class="line"><span>COPY user-data \${WWW_DIR}/user-data</span></span></code></pre></div><p>重建镜像，并创建和运行一个新的容器，这次使用用户数据信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Build a new image named cloud-init:03</span></span>
<span class="line"><span>podman build -f Containerfile -t cloud-init:03 .</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Run a new container with this new user-data file</span></span>
<span class="line"><span>podman run --rm -p 8080:8080 -it cloud-init:03</span></span></code></pre></div><p>现在，重启 Cloud-init 客户端，观察 Web 服务器上的 Nginx 日志：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>127.0.0.1 - - [09/May/2020:23:01:51 +0000] &quot;GET /meta-data HTTP/1.1&quot; 200 63 &quot;-&quot; &quot;Cloud-Init/17.1&quot; &quot;-&quot;</span></span>
<span class="line"><span>127.0.0.1 - - [09/May/2020:23:01:51 +0000] &quot;GET /user-data HTTP/1.1&quot; 200 298 &quot;-&quot; &quot;Cloud-Init/17.1&quot; &quot;-</span></span></code></pre></div><p>成功了！这一次，元数据和用户数据文件都被送到了 Cloud-init 客户端。</p><h3 id="验证-cloud-init-已运行" tabindex="-1">验证 Cloud-init 已运行 <a class="header-anchor" href="#验证-cloud-init-已运行" aria-label="Permalink to “验证 Cloud-init 已运行”">​</a></h3><p>从上面的日志中，你知道 Cloud-init 在客户端主机上运行并请求元数据和用户数据文件，但它用它们做了什么？你可以在 <code>write_files</code> 部分验证 Cloud-init 是否写入了你在用户数据文件中添加的文件。</p><p>在 Cloud-init 客户端上，检查 <code>/srv/foo</code> 和 <code>/srv/bar</code> 文件的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cd /srv/ &amp;&amp; ls</span></span>
<span class="line"><span>bar foo</span></span>
<span class="line"><span># cat foo</span></span>
<span class="line"><span>&quot;Does cloud-init work?&quot;</span></span>
<span class="line"><span># cat bar</span></span>
<span class="line"><span>&quot;IT SURE DOES!&quot;</span></span></code></pre></div><p>成功了！文件已经写好了，并且有你期望的内容。</p><p>如上所述，还有很多其他模块可以用来配置主机。例如，用户数据文件可以配置成用 <code>apt</code> 添加包、复制 SSH 的 <code>authorized_keys</code>、创建用户和组、配置和运行配置管理工具等等。我在家里的私有云中使用它来复制我的 <code>authorized_keys</code>、创建一个本地用户和组，并设置 sudo 权限。</p><h3 id="你接下来可以做什么" tabindex="-1">你接下来可以做什么 <a class="header-anchor" href="#你接下来可以做什么" aria-label="Permalink to “你接下来可以做什么”">​</a></h3><p>Cloud-init 在家庭实验室中很有用，尤其是专注于云技术的实验室。本文所演示的简单服务对于家庭实验室来说可能并不是超级有用，但现在你已经知道 Cloud-init 是如何工作的了，你可以继续创建一个动态服务，可以用自定义数据配置每台主机，让家里的私有云更类似于主流云提供商提供的服务。</p><p>在数据源稍显复杂的情况下，将新的物理（或虚拟）机器添加到家中的私有云中，可以像插入它们并打开它们一样简单。</p><hr>`,20)),a("p",null,[s[30]||(s[30]=n("via: ",-1)),t(i,{href:"https://opensource.com/article/20/5/create-simple-cloud-init-service-your-homelab"},{default:e(()=>[...s[29]||(s[29]=[n("https://opensource.com/article/20/5/create-simple-cloud-init-service-your-homelab",-1)])]),_:1})]),a("p",null,[s[35]||(s[35]=n("作者：",-1)),t(i,{href:"https://opensource.com/users/clcollins"},{default:e(()=>[...s[31]||(s[31]=[n("Chris Collins",-1)])]),_:1}),s[36]||(s[36]=n(" 选题：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[32]||(s[32]=[n("lujun9972",-1)])]),_:1}),s[37]||(s[37]=n(" 译者：",-1)),t(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[33]||(s[33]=[n("wxy",-1)])]),_:1}),s[38]||(s[38]=n(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[34]||(s[34]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[41]||(s[41]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[39]||(s[39]=[n("LCTT",-1)])]),_:1}),s[42]||(s[42]=n(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:e(()=>[...s[40]||(s[40]=[n("Linux中国",-1)])]),_:1}),s[43]||(s[43]=n(" 荣誉推出",-1))])])}const y=p(r,[["render",c]]);export{T as __pageData,y as default};
